const styles = () => ({
  statContainer: {
    boxShadow: '0px 1px 2px rgba(0,0,0,0.2)',
    display: 'flex',
    padding: '16px',
  },
  statIconContainer: {
    paddingRight: '16px',
    paddingTop: '6px',
  },
  statIcon: {
    color: '#ce4899',
    fontSize: '32px',
  },
  statContent: {
    float: 1,
  },
  statDescription: {
    color: '#1976D2',
  },
});

export default styles;
